static ll minll(ll a, ll b) { return a < b ? a : b; }

static void build(int idx, int l, int r) {
    if (l == r) {
        seg[idx].mn = arr[l];
        return;
    }
    int mid = (l + r) >> 1;
    build(idx << 1, l, mid);
    build(idx << 1 | 1, mid + 1, r);
    seg[idx].mn = minll(seg[idx << 1].mn, seg[idx << 1 | 1].mn);
}

static void update(int idx, int l, int r, int pos, ll val) {
    if (l == r) {
        seg[idx].mn = val;
        arr[pos] = val;
        return;
    }
    int mid = (l + r) >> 1;
    if (pos <= mid) update(idx << 1, l, mid, pos, val);
    else update(idx << 1 | 1, mid + 1, r, pos, val);
    seg[idx].mn = minll(seg[idx << 1].mn, seg[idx << 1 | 1].mn);
}

static ll query(int idx, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return seg[idx].mn;
    int mid = (l + r) >> 1;
    ll ans = LLONG_MAX;
    if (ql <= mid) ans = minll(ans, query(idx << 1, l, mid, ql, qr));
    if (qr > mid) ans = minll(ans, query(idx << 1 | 1, mid + 1, r, ql, qr));
    return ans;
}

/* Circular right shift on [l..r]:
   a[r] <- a[r-1], ..., a[l+1] <- a[l], a[l] <- old a[r]
*/
static void circular_shift(int l, int r) {
    if (l >= r) return;
    ll last = arr[r];
    for (int i = r; i > l; --i) {
        arr[i] = arr[i - 1];
        update(1, 0, n - 1, i, arr[i]);
    }
    arr[l] = last;
    update(1, 0, n - 1, l, last);
}

