    // Segment Tree for range minimum query + point update
    static class SegmentTree {
        int n;
        long[] tree;

        SegmentTree(long[] arr) {
            n = arr.length;
            tree = new long[4 * n];
            build(1, 0, n - 1, arr);
        }

        void build(int node, int l, int r, long[] arr) {
            if (l == r) {
                tree[node] = arr[l];
                return;
            }
            int mid = (l + r) >>> 1;
            build(node << 1, l, mid, arr);
            build(node << 1 | 1, mid + 1, r, arr);
            tree[node] = Math.min(tree[node << 1], tree[node << 1 | 1]);
        }

        void update(int idx, long val) {
            update(1, 0, n - 1, idx, val);
        }

        void update(int node, int l, int r, int idx, long val) {
            if (l == r) {
                tree[node] = val;
                return;
            }
            int mid = (l + r) >>> 1;
            if (idx <= mid) update(node << 1, l, mid, idx, val);
            else update(node << 1 | 1, mid + 1, r, idx, val);
            tree[node] = Math.min(tree[node << 1], tree[node << 1 | 1]);
        }

        long query(int ql, int qr) {
            return query(1, 0, n - 1, ql, qr);
        }

        long query(int node, int l, int r, int ql, int qr) {
            if (ql <= l && r <= qr) return tree[node];
            int mid = (l + r) >>> 1;
            long res = Long.MAX_VALUE;
            if (ql <= mid) res = Math.min(res, query(node << 1, l, mid, ql, qr));
            if (qr > mid) res = Math.min(res, query(node << 1 | 1, mid + 1, r, ql, qr));
            return res;
        }
    }

