struct SegmentTree {
    int n;
    vector<int> tree, lazy;

    SegmentTree(vector<int>& arr) {
        n = arr.size();
        tree.resize(4 * n);
        lazy.resize(4 * n, 0);
        build(0, 0, n - 1, arr);
    }

    void build(int node, int l, int r, vector<int>& arr) {
        if (l == r) {
            tree[node] = arr[l];
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node + 1, l, mid, arr);
        build(2 * node + 2, mid + 1, r, arr);
        tree[node] = min(tree[2 * node + 1], tree[2 * node + 2]);
    }

    void apply(int node, int l, int r, int shift) {
        lazy[node] = (lazy[node] + shift) % (r - l + 1);
    }

    void push(int node, int l, int r) {
        if (lazy[node] != 0) {
            if (l != r) {
                int mid = (l + r) / 2;
                apply(2 * node + 1, l, mid, lazy[node]);
                apply(2 * node + 2, mid + 1, r, lazy[node]);
            }
            lazy[node] = 0;
        }
    }

    int getPos(int node, int l, int r, int idx) {
        if (l == r) return tree[node];
        push(node, l, r);
        int mid = (l + r) / 2;
        if (idx <= mid)
            return getPos(2 * node + 1, l, mid, idx);
        else
            return getPos(2 * node + 2, mid + 1, r, idx);
    }

    void shiftRange(int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            apply(node, l, r, 1);
            return;
        }
        push(node, l, r);
        int mid = (l + r) / 2;
        shiftRange(2 * node + 1, l, mid, ql, qr);
        shiftRange(2 * node + 2, mid + 1, r, ql, qr);
        int leftVal = getPosInNode(2 * node + 1, l, mid);
        int rightVal = getPosInNode(2 * node + 2, mid + 1, r);
        tree[node] = min(leftVal, rightVal);
    }

    int getPosInNode(int node, int l, int r) {
        if (l == r) return tree[node];
        push(node, l, r);
        int mid = (l + r) / 2;
        return min(getPosInNode(2 * node + 1, l, mid),
                   getPosInNode(2 * node + 2, mid + 1, r));
    }

    void update(int node, int l, int r, int pos, int val) {
        if (l == r) {
            tree[node] = val;
            return;
        }
        push(node, l, r);
        int mid = (l + r) / 2;
        if (pos <= mid)
            update(2 * node + 1, l, mid, pos, val);
        else
            update(2 * node + 2, mid + 1, r, pos, val);
        tree[node] = min(tree[2 * node + 1], tree[2 * node + 2]);
    }

    int query(int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return INT_MAX;
        if (ql <= l && r <= qr) {
            return getPosInNode(node, l, r);
        }
        push(node, l, r);
        int mid = (l + r) / 2;
        return min(query(2 * node + 1, l, mid, ql, qr),
                   query(2 * node + 2, mid + 1, r, ql, qr));
    }
};

