mt19937 rng(42);

struct Node {
    int val, mn, sz, pri;
    Node *l, *r;
    Node(int v) : val(v), mn(v), sz(1), pri(rng()), l(nullptr), r(nullptr) {}
};

int sz(Node* t) { return t ? t->sz : 0; }
int mn(Node* t) { return t ? t->mn : INT_MAX; }

void upd(Node* t) {
    if (t) {
        t->sz = 1 + sz(t->l) + sz(t->r);
        t->mn = min({t->val, mn(t->l), mn(t->r)});
    }
}

pair<Node*, Node*> split(Node* t, int k) { // left has k nodes
    if (!t) return {nullptr, nullptr};
    if (sz(t->l) >= k) {
        auto [l, r] = split(t->l, k);
        t->l = r; upd(t);
        return {l, t};
    } else {
        int leftSz = sz(t->l) + 1;
        auto [l, r] = split(t->r, k - leftSz);
        t->r = l; upd(t);
        return {t, r};
    }
}

Node* merge(Node* l, Node* r) {
    if (!l) return r;
    if (!r) return l;
    if (l->pri > r->pri) {
        l->r = merge(l->r, r); upd(l); return l;
    } else {
        r->l = merge(l, r->l); upd(r); return r;
    }
}

