struct SegTree {
    int n;
    vector<long long> st, lazy;

    SegTree() {}
    SegTree(const vector<long long>& a) { init(a); }

    void init(const vector<long long>& a) {
        n = (int)a.size();
        st.assign(4 * n, 0);
        lazy.assign(4 * n, 0);
        build(1, 0, n - 1, a);
    }

    void build(int p, int l, int r, const vector<long long>& a) {
        if (l == r) {
            st[p] = a[l];
            return;
        }
        int m = (l + r) >> 1;
        build(p << 1, l, m, a);
        build(p << 1 | 1, m + 1, r, a);
        st[p] = min(st[p << 1], st[p << 1 | 1]);
    }

    void push(int p) {
        if (lazy[p] != 0) {
            long long v = lazy[p];
            st[p << 1] += v;
            st[p << 1 | 1] += v;
            lazy[p << 1] += v;
            lazy[p << 1 | 1] += v;
            lazy[p] = 0;
        }
    }

    void range_add(int p, int l, int r, int i, int j, long long val) {
        if (i > r || j < l) return;
        if (i <= l && r <= j) {
            st[p] += val;
            lazy[p] += val;
            return;
        }
        push(p);
        int m = (l + r) >> 1;
        range_add(p << 1, l, m, i, j, val);
        range_add(p << 1 | 1, m + 1, r, i, j, val);
        st[p] = min(st[p << 1], st[p << 1 | 1]);
    }

    long long range_min(int p, int l, int r, int i, int j) {
        if (i > r || j < l) return LLONG_MAX;
        if (i <= l && r <= j) return st[p];
        push(p);
        int m = (l + r) >> 1;
        return min(range_min(p << 1, l, m, i, j),
                   range_min(p << 1 | 1, m + 1, r, i, j));
    }

    long long point_get(int p, int l, int r, int idx) {
        if (l == r) return st[p];
        push(p);
        int m = (l + r) >> 1;
        if (idx <= m) return point_get(p << 1, l, m, idx);
        return point_get(p << 1 | 1, m + 1, r, idx);
    }

    void point_set(int idx, long long val) {
        long long cur = point_get(1, 0, n - 1, idx);
        range_add(1, 0, n - 1, idx, idx, val - cur);
    }

    void circular_add(int l, int r, long long val) {
        if (l <= r) {
            range_add(1, 0, n - 1, l, r, val);
        } else {
            range_add(1, 0, n - 1, l, n - 1, val);
            range_add(1, 0, n - 1, 0, r, val);
        }
    }

    long long circular_min(int l, int r) {
        if (l <= r) return range_min(1, 0, n - 1, l, r);
        return min(range_min(1, 0, n - 1, l, n - 1),
                   range_min(1, 0, n - 1, 0, r));
    }
};

