import sys
input = sys.stdin.readline

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.tree = [float('inf')] * (2 * self.size)
        for i in range(self.n):
            self.tree[self.size + i] = data[i]
        for i in range(self.size - 1, 0, -1):
            self.tree[i] = min(self.tree[2*i], self.tree[2*i+1])

    def update(self, pos, value):
        idx = self.size + pos
        self.tree[idx] = value
        idx //= 2
        while idx:
            self.tree[idx] = min(self.tree[2*idx], self.tree[2*idx+1])
            idx //= 2

    def query(self, l, r):
        l += self.size
        r += self.size
        res = float('inf')
        while l <= r:
            if l % 2 == 1:
                res = min(res, self.tree[l])
                l += 1
            if r % 2 == 0:
                res = min(res, self.tree[r])
                r -= 1
            l //= 2
            r //= 2
        return res

def main():
    n, q = map(int, input().split())
    arr = list(map(int, input().split()))
    seg = SegmentTree(arr)

    for _ in range(q):
        parts = input().split()
        t = int(parts[0])
        if t == 1:
            l, r = map(int, parts[1:])
            # circular shift right by 1 in [l, r]
            last = arr[r]
            for i in range(r, l, -1):
                arr[i] = arr[i-1]
                seg.update(i, arr[i])
            arr[l] = last
            seg.update(l, last)
        elif t == 2:
            l, r = map(int, parts[1:])
            print(seg.query(l, r))
        else:
            pos, val = map(int, parts[1:])
            arr[pos] = val
            seg.update(pos, val)

if __name__ == "__main__":
    main()
